// Linux/firmware are fetched directly from upstream, not redistributed by this
// demo. See LINUX-SOURCES.md for provenance and corresponding-source caveats.
// The CPython runtime is a same-origin build artifact assembled from pinned
// Alpine packages; its exact hash is generated by scripts/fetch-python-runtime.sh.
import { pythonRuntime } from './python-runtime.mjs';

export { pythonRuntime };

export const bootAssets = [
  ['bios', 'https://raw.githubusercontent.com/copy/v86/d96be774e549a83371b038b86e819804c96b921f/bios/seabios.bin', '73e3f359102e3a9982c35fce98eb7cd08f18303ac7f1ba6ebfbe6cdc1c244d98'],
  ['vga_bios', 'https://raw.githubusercontent.com/copy/v86/d96be774e549a83371b038b86e819804c96b921f/bios/vgabios.bin', 'a4bc0d80cc3ca028c73dafa8fee396b8d054ce87ebd8abfbd31b06b437607880'],
  ['bzimage', 'https://i.copy.sh/buildroot-bzimage68.bin', '507a759c70ab7a490a233be454d0b5b88bc667956a410b531cb4edc091e2eb1c'],
];

export async function sha256Hex(bytes) {
  const view = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  return [...new Uint8Array(await crypto.subtle.digest('SHA-256', view))].map(b => b.toString(16).padStart(2, '0')).join('');
}

export async function verifyPythonRuntime(bytes) {
  if (!(bytes instanceof Uint8Array)) throw Error('Python runtime asset is not binary data');
  if (bytes.byteLength !== pythonRuntime.bytes) throw Error(`Python runtime is ${bytes.byteLength} bytes; expected ${pythonRuntime.bytes}`);
  const hash = await sha256Hex(bytes);
  if (hash !== pythonRuntime.sha256) throw Error(`Python runtime SHA-256 mismatch: ${hash}`);
  return bytes;
}

export async function fetchPythonRuntime() {
  const response = await fetch(new URL('./' + pythonRuntime.file, import.meta.url), {
    credentials: 'omit', referrerPolicy: 'no-referrer', signal: AbortSignal.timeout(120000),
  });
  if (!response.ok) throw Error(`Python runtime: HTTP ${response.status}`);
  return verifyPythonRuntime(new Uint8Array(await response.arrayBuffer()));
}

export async function fetchBootAssets() {
  return Object.fromEntries(await Promise.all(bootAssets.map(async ([name, url, expected]) => {
    const response = await fetch(url, { credentials: 'omit', referrerPolicy: 'no-referrer', signal: AbortSignal.timeout(120000) });
    if (!response.ok) throw Error(`${name}: upstream HTTP ${response.status}`);
    const buffer = await response.arrayBuffer();
    const hash = await sha256Hex(buffer);
    if (hash !== expected) throw Error(`${name}: SHA-256 mismatch; refusing to boot`);
    return [name, { buffer }];
  })));
}
